    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1

    # The separator is the uniform row or column whose color is rarest overall.
    candidates = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            candidates.append((freq[grid[r][0]], "h", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((freq[grid[0][c]], "v", c))

    _, orient, k = min(candidates)
    if orient == "h":
        a, b = grid[:k], grid[k + 1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    base = max(common, key=lambda x: sum(row.count(x) for row in a) +
                                      sum(row.count(x) for row in b))

    rows = min(len(a), len(b))
    cols = min(len(a[0]), len(b[0]))
    return [
        [3 if a[r][c] == b[r][c] else base for c in range(cols)]
        for r in range(rows)
    ]
